// TecOps F — relatório semanal detalhado, com categorias explícitas e sem preencher lacunas.
const envelope = $input.first().json || {};
const data = envelope.data || {};
const jobs = [...(Array.isArray(data.vagas) ? data.vagas : []),
  ...(Array.isArray(data.historicoVagas) ? data.historicoVagas : [])];
const events = Array.isArray(data.eventosHistorico) ? data.eventosHistorico : [];
const reports = Array.isArray(envelope.reportsArchive?.reports) ? envelope.reportsArchive.reports : [];

const today = new Date();
const monday = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()));
monday.setUTCDate(monday.getUTCDate() - (monday.getUTCDay() + 6) % 7);
const start = new Date(monday.getTime() - 7 * 86400000);
const since = start.toISOString(), until = monday.toISOString();
const weekKey = since.slice(0, 10);
const within = value => {
  const parsed = Date.parse(value || '');
  return Number.isFinite(parsed) && parsed >= start.getTime() && parsed < monday.getTime();
};
const norm = value => String(value ?? '').normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const clean = value => String(value ?? '').replace(/\s+/g, ' ').trim();
const valueOr = value => {
  const result = clean(value);
  return result && !['nao informada', 'nao informado', 'ver anuncio', 'n/a', 'null', 'undefined'].includes(norm(result))
    ? result : 'Não informado';
};
const unique = values => [...new Set(values.map(value => clean(value)).filter(Boolean))];
const jobById = new Map(jobs.filter(job => job && job.id).map(job => [String(job.id), job]));
const fromIds = ids => [...new Set(ids.map(String))].map(id => jobById.get(id)).filter(Boolean);
const status = job => clean(job.statusCandidatura || job.application_status || 'PENDING_VALIDATION').toUpperCase();
const lastVerified = job => job.last_verified_at || job.ultimaVerificacaoCandidatura || null;
const recentActive = job => status(job) === 'ACTIVE' && (() => {
  const parsed = Date.parse(lastVerified(job) || '');
  return Number.isFinite(parsed) && parsed >= start.getTime() && parsed <= Date.now();
})();
const thisWeekEvents = events.filter(event => within(event.em));
const archivedReports = reports.filter(report => report.weekKey && report.weekKey < weekKey);
const reportedBefore = new Set(archivedReports.flatMap(report => report.reportedJobIds || []).map(String));
const priority = job => {
  const value = Number(job.compatibility_score);
  return job.compatibility_score == null || job.compatibility_score === '' || !Number.isFinite(value) ? -1 : value;
};
const sortByScore = list => [...list].sort((a, b) =>
  priority(b) - priority(a) || clean(a.cargo || a.title).localeCompare(clean(b.cargo || b.title), 'pt-BR'));

function classify(job) {
  const title = norm(job.cargo || job.title);
  const level = norm(job.nivel || job.job_level);
  const type = norm([job.employment_type, job.job_type, job.tipoContrato].filter(Boolean).join(' '));
  const areas = norm([job.area, ...(Array.isArray(job.areas) ? job.areas : [])].join(' '));
  const text = title + ' ' + areas;
  const internship = /\b(estagio|estagiari[ao]|intern(ship)?|aprendiz)\b/.test(title + ' ' + level + ' ' + type);
  const development = /\b(desenvolvimento|desenvolvedor[ao]?|developer|programador[ao]?|software|engenharia de software|backend|back.?end|front.?end|full.?stack|mobile|web|jogos|unity|godot|unreal)\b/.test(text);
  const qa = /\b(qa|quality assurance|quality engineer|quality analyst|qualidade de software|tester|testing|testes?|automacao de testes|sdet)\b/.test(text);
  const integration = /\b(integrac(?:ao|oes)|integration|integrador[ao]?|middleware|sistemas integrados|erp|iot|embarcados)\b/.test(text);
  const junior = /\b(junior|jr)\b/.test(title + ' ' + level);
  // Estágio prevalece quando é explicitamente de desenvolvimento; especialidades
  // QA e integração ficam em grupos próprios (inclusive estágios nessas áreas).
  if (internship && development && !qa && !integration)
    return {key:'internships',reason:'Estágio identificado no nível/título e atividade de desenvolvimento informada.'};
  if (qa) return {key:'qaTesting',reason:'Cargo ou área informada contém QA, testes ou automação de testes.'};
  if (integration) return {key:'systemIntegration',reason:'Cargo ou área informada indica integração de sistemas ou especialidade correlata.'};
  if (junior && development && !internship)
    return {key:'juniorDevelopment',reason:'Cargo/nível indica desenvolvimento júnior, sem indicação de estágio; vínculo empregatício deve ser confirmado na fonte.'};
  if (internship && development)
    return {key:'internships',reason:'Estágio de desenvolvimento identificado no cargo ou nível.'};
  return {key:'otherNew',reason:'Não há evidências suficientes no cargo/área para enquadrar nas quatro especialidades.'};
}

const newConfirmed = sortByScore(fromIds(thisWeekEvents.filter(e => e.tipo === 'nova').map(e => e.id))
  .filter(recentActive));
const groups = {juniorDevelopment:[], internships:[], qaTesting:[], systemIntegration:[], otherNew:[]};
for (const job of newConfirmed) groups[classify(job).key].push(job);
const freshIds = new Set(newConfirmed.map(j => String(j.id)));
const previous = sortByScore(jobs.filter(job => {
  if (!job || !job.id || freshIds.has(String(job.id))) return false;
  if (['CLOSED','EXPIRED'].includes(status(job))) return false;
  const seen = Date.parse(job.first_seen_at || job.primeiraIdentificacao || '');
  return reportedBefore.has(String(job.id)) ||
    (Number.isFinite(seen) && seen < start.getTime());
}));
const closed = sortByScore(jobs.filter(job => {
  if (!job?.id || !['CLOSED', 'EXPIRED'].includes(status(job))) return false;
  return thisWeekEvents.some(event => event.tipo === 'encerrada' && String(event.id) === String(job.id)) ||
    (reportedBefore.has(String(job.id)) && within(lastVerified(job)));
}));
const updated = sortByScore(fromIds(thisWeekEvents.filter(e => e.tipo === 'atualizada').map(e => e.id))
  .filter(job => !['CLOSED','EXPIRED'].includes(status(job))));
const unverified = sortByScore(jobs.filter(job => {
  if (!job?.id || ['ACTIVE','CLOSED','EXPIRED'].includes(status(job))) return false;
  return within(job.last_seen_at || job.ultimaIdentificacao) ||
    within(lastVerified(job)) || within(job.first_seen_at || job.primeiraIdentificacao) ||
    reportedBefore.has(String(job.id));
}));

function dateText(value, withTime = false) {
  if (!value) return 'Não informado';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return 'Não informado';
  if (!withTime && /^\d{4}-\d{2}-\d{2}$/.test(String(value))) {
    const [y, m, d] = String(value).split('-');
    return d + '/' + m + '/' + y;
  }
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric',
    ...(withTime ? {hour:'2-digit',minute:'2-digit',hour12:false} : {})
  }).format(parsed);
}
function salaryText(job) {
  const numeric = value => value !== null && value !== undefined && value !== '' &&
    Number.isFinite(Number(value)) && Number(value) >= 0 ? Number(value) : null;
  const min = numeric(job.salary_min ?? job.salarioMinimo);
  const max = numeric(job.salary_max ?? job.salarioMaximo);
  const currency = clean(job.salary_currency || job.moedaSalario).toUpperCase();
  const amount = value => {
    const formatted = value.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
    if (/^[A-Z]{3}$/.test(currency)) {
      try { return new Intl.NumberFormat('pt-BR',{style:'currency',currency}).format(value); }
      catch { return formatted + ' ' + currency; }
    }
    return formatted + ' (moeda não informada)';
  };
  if (min !== null && max !== null) return min === max ? amount(min) : amount(min) + ' a ' + amount(max);
  if (min !== null) return 'A partir de ' + amount(min);
  if (max !== null) return 'Até ' + amount(max);
  const stated = clean(job.salarioInformado || job.salary_text || job.salaryText || '');
  return stated ? stated : 'Não informado';
}
function educationText(job) {
  // Só aceita exigências declaradas em campos próprios, nunca deduz formação
  // a partir de competências, score ou área profissional.
  const fields = ['formacaoExigida','educacaoExigida','education_requirement',
    'educationRequirements','required_education','requiredEducation'];
  for (const field of fields) {
    const value = job[field];
    const values = Array.isArray(value) ? value : [value];
    const explicit = values.map(item => typeof item === 'object' && item !== null
      ? clean(item.name || item.description || item.credentialCategory) : clean(item))
      .filter(Boolean);
    if (explicit.length) return explicit.join('; ');
  }
  return 'Não informada';
}
function experienceText(job) {
  const required = job.experienciaObrigatoriaAnos;
  const desired = job.experienciaDesejavelAnos;
  const valid = value => value !== null && value !== undefined && value !== '' &&
    Number.isFinite(Number(value)) && Number(value) >= 0;
  const pieces = [];
  if (valid(required)) pieces.push('Obrigatória: ' + Number(required) + ' ano(s)');
  if (valid(desired)) pieces.push('Desejável: ' + Number(desired) + ' ano(s)');
  if (pieces.length) return pieces.join('; ');
  const classified = norm(job.experienciaClassificacao || job.classificacaoExperiencia || '');
  const experience = norm(job.experiencia || job.experience_requirement || '');
  if (classified === 'experiencia_obrigatoria' || experience === 'obrigatoria') return 'Obrigatória (tempo não informado)';
  if (classified === 'experiencia_diferencial' || experience === 'desejavel') return 'Desejável (tempo não informado)';
  if (classified === 'sem_experiencia' || experience === 'nao exigida') return 'Não exigida (conforme classificação)';
  if (classified === 'experiencia_inicial') return 'Projetos/estágios aceitos (conforme classificação)';
  if (experience && !['nao informada','nao informado'].includes(experience))
    return valueOr(job.experiencia || job.experience_requirement);
  return 'Não informada';
}
function httpsUrl(value) {
  try {
    const url = new URL(String(value || ''));
    if (url.protocol !== 'https:' || url.username || url.password) return null;
    return url.href;
  } catch { return null; }
}
function officialUrl(job) {
  // Um link para uma issue ou agregador não comprova que seja a URL OFICIAL.
  const explicit = job.official_application_url || job.officialApplicationUrl ||
    job.linkCandidaturaOficial || job.urlCandidaturaOficial;
  if (explicit) return httpsUrl(explicit);
  if (job.linkOficialConfirmado === true || job.applicationUrlVerified === true)
    return httpsUrl(job.application_url || job.link);
  return null;
}
function sourceUrl(job) {
  // Prioriza o permalink da fonte, indispensável na atribuição Himalayas.
  return httpsUrl(job.source_url || job.guid || job.link || job.application_url);
}
function applicationLinkFromSource(job) {
  return /himalayas/i.test(String(job.fonte||job.source||''))
    ? httpsUrl(job.application_url||job.link) : null;
}
function statusText(job) {
  const state = status(job);
  if (state === 'ACTIVE') return recentActive(job) ?
    'Aberta conforme última verificação recente' : 'Anteriormente ativa; abertura não revalidada recentemente';
  if (state === 'CLOSED') return 'Encerrada';
  if (state === 'EXPIRED') return 'Prazo expirado';
  if (state === 'SOURCE_UNAVAILABLE') return 'Fonte indisponível; situação não confirmada';
  return 'Candidatura não confirmada';
}
function detail(job, key) {
  const classification = classify(job);
  const reasons = [];
  if (key === 'previous') reasons.push('Oportunidade encontrada anteriormente, preservada no histórico.');
  else if (key === 'closed') reasons.push('Status encerrado/expirado registrado na verificação.');
  else if (key === 'updated') reasons.push('Atualização registrada no histórico durante o período.');
  else if (key === 'unverified') reasons.push('Não foi possível confirmar a candidatura na fonte.');
  else reasons.push(classification.reason);
  if (clean(job.justificativaClassificacao)) reasons.push('Classificação da origem: ' + clean(job.justificativaClassificacao));
  return {
    id: String(job.id),
    cargo: valueOr(job.cargo || job.title),
    empresa: valueOr(job.empresa || job.company),
    modalidade: valueOr(job.modalidade || job.work_mode),
    localidade: valueOr(job.local || job.location),
    salario: salaryText(job),
    tecnologias: unique(Array.isArray(job.tecnologias) ? job.tecnologias :
      Array.isArray(job.technologies) ? job.technologies : []).join(', ') || 'Não informadas',
    formacaoExigida: educationText(job),
    experiencia: experienceText(job),
    prazoInscricao: dateText(job.expiraEm || job.deadline),
    compatibilidade: job.compatibility_score !== null && job.compatibility_score !== undefined &&
      job.compatibility_score !== '' && Number.isFinite(Number(job.compatibility_score)) &&
      Number(job.compatibility_score) >= 0 && Number(job.compatibility_score) <= 100
      ? String(job.compatibility_score) + '/100' : 'Não calculada',
    motivoClassificacao: reasons.join(' '),
    motivoCompatibilidade: valueOr(job.compatibility_notes),
    ultimaValidacao: dateText(lastVerified(job), true),
    statusCandidatura: statusText(job),
    urlOficial: officialUrl(job),
    urlFonte: sourceUrl(job),
    urlCandidaturaFonte: applicationLinkFromSource(job)
  };
}
const sections = [
  {key:'juniorDevelopment', title:'1. Vagas efetivas de desenvolvimento júnior',list:groups.juniorDevelopment,
    empty:'Nenhuma nova vaga júnior de desenvolvimento com candidatura confirmada.'},
  {key:'internships',title:'2. Estágios em desenvolvimento',list:groups.internships,
    empty:'Nenhum novo estágio em desenvolvimento com candidatura confirmada.'},
  {key:'qaTesting',title:'3. QA e automação de testes',list:groups.qaTesting,
    empty:'Nenhuma nova vaga de QA/testes com candidatura confirmada.'},
  {key:'systemIntegration',title:'4. Integração de sistemas e áreas correlatas',list:groups.systemIntegration,
    empty:'Nenhuma nova vaga de integração com candidatura confirmada.'},
  {key:'previous',title:'5. Oportunidades anteriormente encontradas',list:previous,
    empty:'Nenhuma oportunidade anterior disponível no histórico para esta seção.'},
  {key:'closed',title:'6. Vagas encerradas',list:closed,
    empty:'Nenhum encerramento confirmado no período.'},
  {key:'otherNew',title:'Outras novas oportunidades confirmadas (não enquadradas nas quatro áreas)',list:groups.otherNew,
    empty:'Nenhuma oportunidade adicional.'},
  {key:'updated',title:'Oportunidades atualizadas (informação complementar)',list:updated,
    empty:'Nenhuma atualização relevante identificada nesta semana.'},
  {key:'unverified',title:'Vagas que não puderam ser verificadas (informação complementar)',list:unverified,
    empty:'Nenhuma vaga pendente de verificação nesta semana.'}
];
const records = Object.fromEntries(sections.map(section =>
  [section.key, section.list.map(job => detail(job,section.key))]));
const counts = {
  new:newConfirmed.length, continued:previous.filter(recentActive).length,
  closed:closed.length, updated:updated.length, unverified:unverified.length,
  juniorDevelopment:groups.juniorDevelopment.length,internships:groups.internships.length,
  qaTesting:groups.qaTesting.length,systemIntegration:groups.systemIntegration.length,
  previous:previous.length,otherNew:groups.otherNew.length
};
const noNews = 'Nenhuma nova vaga confirmada foi encontrada nesta semana.';
const newsSummary = !counts.new ? noNews :
  counts.new === 1 ? 'Foi confirmada 1 nova oportunidade.' :
  'Foram confirmadas ' + counts.new + ' novas oportunidades.';
const header = 'Relatório semanal TecOps — ' + weekKey + ' a ' +
  new Date(monday.getTime()-86400000).toISOString().slice(0,10);
const fields = [
  ['Cargo','cargo'],['Empresa','empresa'],['Modalidade','modalidade'],
  ['Localidade','localidade'],['Salário','salario'],['Tecnologias','tecnologias'],
  ['Formação exigida','formacaoExigida'],
  ['Experiência obrigatória ou desejável','experiencia'],
  ['Prazo de inscrição','prazoInscricao'],['Compatibilidade com o perfil','compatibilidade'],
  ['Motivo da classificação','motivoClassificacao'],
  ['Motivo da compatibilidade','motivoCompatibilidade'],
  ['Data da última validação','ultimaValidacao'],
  ['Situação da candidatura','statusCandidatura']
];
const renderTextJob = (item,index) => {
  const lines = [(index+1) + '. ' + item.cargo];
  for (const [title,field] of fields) lines.push('   ' + title + ': ' + item[field]);
  lines.push('   Link oficial para candidatura: ' + (item.urlOficial || 'Não informado / não confirmado pela fonte'));
  lines.push('   Link de candidatura disponibilizado pela fonte: ' + (item.urlCandidaturaFonte || 'Não informado'));
  lines.push('   Link do anúncio na fonte: ' + (item.urlFonte || 'Não informado'));
  return lines.join('\n');
};
const renderTextSection = section => section.title + ' (' + records[section.key].length + ')\n' +
  (records[section.key].length ? records[section.key].map(renderTextJob).join('\n\n') : section.empty);
const note = 'Observações: a categoria de júnior indica vaga não identificada como estágio e não comprova contratação efetiva/CLT. ' +
  'Informações ausentes permanecem como não informadas. Links de agregadores e issues não são identificados como links oficiais sem confirmação. ' +
  'Abertura depende de verificação recente; indisponibilidade da fonte não prova encerramento. ' +
  'As seções complementares podem repetir oportunidades das seis categorias principais.';
const textReport = [header,'Novas oportunidades confirmadas',newsSummary,
  'Oportunidades anteriormente reportadas que continuam abertas: ' + counts.continued,
  ...sections.map(renderTextSection),note].join('\n\n');
const escape = value => String(value).replace(/[&<>"']/g, char =>
  ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const htmlItem = item => '<li style="margin:0 0 18px;padding:12px;border:1px solid #ddd;border-radius:8px">' +
  '<strong>' + escape(item.cargo) + '</strong>' +
  '<dl>' + fields.map(([title,key]) => '<dt style="font-weight:bold;margin-top:5px">' +
    escape(title) + '</dt><dd style="margin-left:0">' + escape(item[key]) + '</dd>').join('') +
  '<dt style="font-weight:bold;margin-top:5px">Link oficial para candidatura</dt><dd style="margin-left:0">' +
  (item.urlOficial ? '<a href="' + escape(item.urlOficial) + '">' + escape(item.urlOficial) + '</a>' :
    'Não informado / não confirmado pela fonte') + '</dd>' +
  '<dt style="font-weight:bold;margin-top:5px">Link de candidatura disponibilizado pela fonte</dt><dd style="margin-left:0">' +
  (item.urlCandidaturaFonte ? '<a href="' + escape(item.urlCandidaturaFonte) + '">' + escape(item.urlCandidaturaFonte) + '</a>' : 'Não informado') +
  '</dd>' +
  '<dt style="font-weight:bold;margin-top:5px">Link do anúncio na fonte</dt><dd style="margin-left:0">' +
  (item.urlFonte ? '<a href="' + escape(item.urlFonte) + '">' + escape(item.urlFonte) + '</a>' : 'Não informado') +
  '</dd></dl></li>';
const html = '<div style="font-family:Arial,sans-serif;line-height:1.5;color:#1f2937;max-width:760px">' +
  '<h1>' + escape(header) + '</h1>' +
  '<p><strong>' + escape(newsSummary) + '</strong></p>' +
  '<p>Oportunidades anteriormente reportadas que continuam abertas: ' + counts.continued + '</p>' +
  sections.map(section => '<h2>' + escape(section.title) + ' (' + records[section.key].length + ')</h2>' +
    (records[section.key].length ? '<ol style="padding-left:24px">' +
      records[section.key].map(htmlItem).join('') + '</ol>' :
      '<p>' + escape(section.empty) + '</p>')).join('') +
  '<p><small>' + escape(note) + '</small></p></div>';
const reportedJobIds = unique(sections.flatMap(section => section.list.map(job => String(job.id)))).sort();
const report = {
  weekKey, generatedAt:new Date().toISOString(),since,until,counts,reportedJobIds,
  sections:{
    new:newConfirmed.map(job => job.id),continued:previous.filter(recentActive).map(job => job.id),
    closed:closed.map(job => job.id),updated:updated.map(job => job.id),
    unverified:unverified.map(job => job.id),
    juniorDevelopment:groups.juniorDevelopment.map(job => job.id),
    internships:groups.internships.map(job => job.id),
    qaTesting:groups.qaTesting.map(job => job.id),
    systemIntegration:groups.systemIntegration.map(job => job.id),
    previous:previous.map(job => job.id),otherNew:groups.otherNew.map(job => job.id)
  },
  records,text:textReport
};
return [{json:{...envelope,report,reportText:textReport,reportHtml:html,
  reportSubject:'TecOps — Relatório semanal '+weekKey,
  messageNoNewConfirmed:counts.new===0}}];
